mapper.select:
select s.*, c.category_name, b.brand_name from mall_spu s join mall_category c on c.category_id = s.category_id and c.del_flag = '0' and c.status = '0' left join mall_brand b on b.brand_id = s.brand_id and b.del_flag = '0' where s.del_flag = '0' and s.publish_status = '1' and s.category_id = #{categoryId}
and (s.product_name like concat('%', #{keyword}, '%') or c.category_name like concat('%', #{keyword}, '%') or b.brand_name like concat('%', #{keyword}, '%'))
order by s.sales_count desc, s.sort_no asc, s.spu_id desc order by s.price_min asc, s.sort_no asc, s.spu_id desc order by s.price_min desc, s.sort_no asc, s.spu_id desc order by s.sort_no asc, s.spu_id desc
